def _partially_consume_prefix(self, prefix, column):
    lines = []
    current_line = ""
    current_column = 0
    wait_for_nl = False
    for char in prefix:
        if char == '\t':
            current_column += 1  # Treat tabs as a single column
        elif char == ' ':
            current_column += 1
        elif char == '\n':
            if wait_for_nl:
                if current_line.strip() and current_column < column:
                    res = ''.join(lines)
                    return res, prefix[len(res):]

                lines.append(current_line)
                current_line = ""
                current_column = 0
                wait_for_nl = False
            else:
                current_column = 0
        else:
            wait_for_nl = True

        current_line += char

    return ''.join(lines), current_line
